<?php
require __DIR__.'/../../config/database.php';require __DIR__.'/../../config/helpers.php';if(!isset($_SESSION['ID_USER'])){header('Location: /index.php');exit;}requireRole(1);$lab=max(1,min(4,(int)($_GET['lab']??1)));$s=$con->prepare('SELECT o.ID_OCORR,o.titulo,o.descricao,o.data_ocorr,o.ID_MAQ,o.tipo_problema,o.status_ocorrencia,u.nome AS reportado_por FROM Ocorrencias o JOIN Usuarios u ON u.ID_USER=o.ID_USER WHERE o.ID_LAB=? ORDER BY o.data_ocorr DESC,o.ID_OCORR DESC');$s->bind_param('i',$lab);$s->execute();$ocorrencias=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relatório geral</title><link rel="stylesheet" href="/assets/css/base.css"><link rel="stylesheet" href="/assets/css/relatorio-geral.css"></head><body><div class="app-shell"><?php renderTopbar('professor','relatorio');?><main class="app-main"><div class="report-wrap"><div class="report-head"><h1>Relatório — Laboratório <?=$lab?></h1><a class="btn btn-accent" href="/professor/relatorio_pdf.php?lab=<?=$lab?>">⬇ Baixar PDF</a></div><table class="report-table"><thead><tr><th>Máquina</th><th>Tipo</th><th>Título</th><th>Status</th><th>Data</th><th>Reportado por</th></tr></thead><tbody><?php foreach($ocorrencias as $o):$info=statusInfo((int)$o['status_ocorrencia']);?><tr><td><?=$o['ID_MAQ']?'#'.(int)$o['ID_MAQ']:'—'?></td><td><?=htmlspecialchars($o['tipo_problema'])?></td><td><?=htmlspecialchars($o['titulo'])?></td><td><span class="status-pill <?=$info['class']?>"><span class="status-dot <?=$info['class']?>"></span><?=$info['label']?></span></td><td><?=htmlspecialchars($o['data_ocorr'])?></td><td><?=htmlspecialchars($o['reportado_por'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$ocorrencias):?><p class="empty-state">Nenhuma ocorrência registrada neste laboratório.</p><?php endif;?></div></main></div></body></html>
